import json,hashlib
from pathlib import Path
P=Path('territory-data/raw');rows=json.loads((P/'northern-officials-next.json').read_text());events=[]
def id_for(state,name):
 x=next(r for r in rows if r['state']==state and r['name']==name)
 return 'office-'+hashlib.sha256((x['chamber']+'|'+state+'|'+name).encode()).hexdigest()[:12]
def add(key,date,title,category,url,state,names,summary,attribution):
 events.append(dict(id=key,date=date,reference_year=int(date[:4]),title=title,category=category,source_url=url,source_name='Radio Nigeria Kaduna (FRCN)',classification='published',level='state constituency / named legislative action',status='Reported legislative activity',qualification='Public broadcaster report, not an independent outcome audit or complete activity register. A motion or debate does not establish enactment, project completion or service improvement.',summary=summary,attribution=attribution,member_ids=[id_for(state,n) for n in names]))
u='https://www.radionigeriakaduna.gov.ng/2026/10/13/kaduna-assembly-seeks-autonomy-for-multi-campus-nursing-college-midwifery/'
add('kaduna-nursing-motion-20261013','2026-10-13','Motion on nursing-college campus autonomy','Motions',u,'Kaduna',['Ali Kalat'],'Reported sponsorship of a motion seeking greater administrative independence for nursing and midwifery campuses. Proposed law changes and outcomes remain unverified.','Article explicitly names Ali Kalat as Jema’a member and motion sponsor.')
add('kaduna-plenary-chair-20261013','2026-10-13','Presided over nursing-college reform deliberations','Plenary participation',u,'Kaduna',['Henry Magaji Danjuma'],'Reported chairing of the plenary considering the campus-autonomy proposal. This is one documented sitting, not a full attendance rate or sponsorship credit.','Article explicitly identifies deputy speaker Henry Magaji Danjuma as presiding; no sponsor credit assigned.')
u='https://www.radionigeriakaduna.gov.ng/2026/09/30/kano-assembly-seeks-polytechnic-campus-in-doguwa-urges-action-on-collapsed-bridges/'
add('kano-doguwa-motion-20260930','2026-09-30','Motion seeking a polytechnic campus in Doguwa','Motions',u,'Kano',['Hon. Salisu Ibrahim Muhammad'],'Reported motion requesting a polytechnic campus. This records advocacy, not a built campus or education outcome.','Exact name and Doguwa constituency match between report and official roster.')
add('kano-gezawa-debate-20260930','2026-09-30','Contribution to tertiary-education debate','Debate contributions',u,'Kano',['Hon. Abdullahi Yahya'],'Reported contribution proposing expansion of an existing Tudun Wada institution rather than a new campus. No implementation is claimed.','Report spelling Abdullah Yahya reviewed against official roster Abdullahi Yahya; both explicitly identify Gezawa constituency.')
u='https://www.radionigeriakaduna.gov.ng/2026/03/04/kano-assembly-demands-solar-streetlights-to-boost-security/'
add('kano-streetlight-motion-20260304','2026-03-04','Joint motion requesting solar-streetlight extension','Motions',u,'Kano',['Hon. Labaran Abdul Madari','Hon. Rabiu Shuaibu','Hon. Ali Abdullahi Manager'],'Reported joint motion for streetlight extension serving Warawa, Dawakin Kudu and Wudil. The resolution does not prove procurement, installation or improved security.','Shortened or reordered names reviewed with the three constituencies explicitly named in the article and official assembly roster. Shared event counted once per named participant, not as three distinct motions.')
add('nasarawa-student-parliament-20260904','2026-09-04','Opened students’ parliamentary sitting as speaker’s representative','Citizen engagement','https://nbs.na.gov.ng/2026/09/03/sule-urges-nigerian-youths-to-embrace-responsible-citizenship/','Nasarawa',['Mohammed Adamu Oyanki'],'Reported participation in the second legislative sitting of the Nasarawa State Students’ Parliament. No attendance rate, programme outcome or personal credit to the absent speaker is assigned.','Report explicitly identifies deputy Mohammed Adamu Oyanki as representing the speaker; only the deputy is attributed.')
events[-1]['source_name']='Nasarawa Broadcasting Service'
add('plateau-peace-delegation-20260429','2026-04-29','Participated in Plateau peace consultation at the State House','Citizen engagement','https://statehouse.gov.ng/plateau-leaders-commit-to-peace-at-interactive-session-with-president-tinubu-fg-approves-n2bn-for-victims/','Plateau',['Rt Hon Naanlong Gapyil Daniel'],'Presidency report lists the speaker among delegates at a peace consultation. No individual speech, vote, spending delivery or subsequent peace outcome is attributed.','Official participant list explicitly identifies the speaker; participation alone is recorded.')
events[-1]['source_name']='State House, Abuja';events[-1]['qualification']='Presidency self-report of participation, not an independent outcome audit, full attendance register or evidence of spending or peace outcomes.'
add('yobe-pac-opening-20261020','2026-10-20','Opened and addressed public-accounts audit review','Oversight','https://dailypost.ng/2026/10/20/appear-before-pac-with-financial-records-yobe-speaker-tells-queried-mdas-lgs/','Yobe',['Rt Hon Chiroma Buba Mashio','Hon. Bulama Bukar'],'Report records the speaker opening a committee session on 2025 state and local-government audit reports and the committee chair addressing it. No completed audit, recovered funds or improved accountability score is claimed.','Mashio explicitly opened the session; Bukar explicitly addressed it as committee chair. Shared activity, distinct roles.')
events[-1]['source_name']='Daily Post Nigeria';events[-1]['qualification']='Dated news report of a named oversight activity, not an audit outcome, recovery total or complete attendance register.'
add('yobe-irrigation-launch-20251205','2025-12-05','Launched farmer-support programme as governor’s representative','Citizen engagement','https://fmino.gov.ng/auda-nepad-and-yobe-state-government-launch-innovative-smallholder-farmers-support-and-youth-smart-irrigation-program/','Yobe',['Rt. Hon. Ya’u Usman Dachia'],'Official release records the deputy speaker launching the smallholder and youth irrigation programme as the governor’s representative. No personal funding, beneficiary total or agricultural outcome is attributed.','Release explicitly identifies Dachia as the governor’s representative who launched the programme.')
events[-1]['source_name']='Federal Ministry of Information and National Orientation / AUDA-NEPAD Nigeria';events[-1]['qualification']='Programme agency self-report of a launch, not an independent delivery or impact audit.'
for e in events:e['date_basis']='Source publication date; not an inferred exact event date.'
events[-1]['date_basis']='Explicit event date: Friday 5 December 2025, also the publication and signed release date.'
(P/'northern-activity-next.json').write_text(json.dumps(events,indent=2,ensure_ascii=False))
print(len(events),'events')
